import { OrderStore, Cart } from './orders';

/** Turn the customer's cart into an order. */
export function placeOrder(cart: Cart) {
  if (!hasItems(cart)) return { error: 'Your cart is empty' };
  const store = new OrderStore();
  const total = calculateTotal(cart);
  return store.save(cart, total);
}

/** Check that there is something to order. */
function hasItems(cart: Cart) {
  return cart.items.length > 0;
}

/** Add up the price of every item, including its quantity. */
function calculateTotal(cart: Cart) {
  return cart.items.reduce((sum, item) => sum + item.price * item.quantity, 0);
}

